import{_ as n,o as a,c as i,a3 as t}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Funktionsplan","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/function-plan.md","filePath":"projects/logic-studio/user-guide/function-plan.md","lastUpdated":1794767190000}'),r={name:"projects/logic-studio/user-guide/function-plan.md"};function l(s,e,d,h,u,o){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="funktionsplan" tabindex="-1">Funktionsplan <a class="header-anchor" href="#funktionsplan" aria-label="Permalink to &quot;Funktionsplan&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Erstelle einen Funktionsplan. Ziehe einen digitalen Eingang und einen Ausgang auf die Fläche. Verbinde den Ausgangspin des Eingangs mit dem Eingangspin des Ausgangs. Starte die Simulation und schalte den Eingang um. Der Ausgang folgt dem Signal.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="zeichenflache" tabindex="-1">Zeichenfläche <a class="header-anchor" href="#zeichenflache" aria-label="Permalink to &quot;Zeichenfläche&quot;">​</a></h3><p>Bausteine ziehen, verschieben und verbinden. Mit Zoom und Einpassen behältst du den Überblick.</p><h3 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter&quot;">​</a></h3><p>Wähle den Baustein und stelle etwa die Zeit eines Timers oder den Sollwert eines Zählers ein.</p><h3 id="ha-ein-und-ausgange" tabindex="-1">HA-Ein- und Ausgänge <a class="header-anchor" href="#ha-ein-und-ausgange" aria-label="Permalink to &quot;HA-Ein- und Ausgänge&quot;">​</a></h3><p>Ordne eine Entität für das Eingangssignal und bei Bedarf eine freigegebene HA-Aktion für den Ausgang zu.</p><h3 id="simulation" tabindex="-1">Simulation <a class="header-anchor" href="#simulation" aria-label="Permalink to &quot;Simulation&quot;">​</a></h3><p>Schalte Eingangswerte um und verfolge die Signale an den Anschlüssen.</p><h3 id="haltepunkt-und-einzelschritt" tabindex="-1">Haltepunkt und Einzelschritt <a class="header-anchor" href="#haltepunkt-und-einzelschritt" aria-label="Permalink to &quot;Haltepunkt und Einzelschritt&quot;">​</a></h3><p>Halte die Simulation an und gehe einen Zyklus weiter, um die Werte zu prüfen.</p><h3 id="anordnen-und-anheften" tabindex="-1">Anordnen und Anheften <a class="header-anchor" href="#anordnen-und-anheften" aria-label="Permalink to &quot;Anordnen und Anheften&quot;">​</a></h3><p>Ordne den Plan automatisch an. Angeheftete Bausteine behalten dabei ihre Position.</p><h3 id="play-und-live-diagnose" tabindex="-1">Play und Live-Diagnose <a class="header-anchor" href="#play-und-live-diagnose" aria-label="Permalink to &quot;Play und Live-Diagnose&quot;">​</a></h3><p>Starte den gespeicherten Plan. Die Diagnose zeigt Werte und Fehler des laufenden Plans.</p><h3 id="zahler-und-merker-speichern" tabindex="-1">Zähler und Merker speichern <a class="header-anchor" href="#zahler-und-merker-speichern" aria-label="Permalink to &quot;Zähler und Merker speichern&quot;">​</a></h3><p>Aktiviere die Option, wenn diese Werte einen App-Neustart überstehen sollen. Eine Änderung am Plan kann den Speicher zurücksetzen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn die Verbindung nicht angenommen wird, vergleiche die Typen beider Anschlüsse. Ein Zahlenausgang passt nicht an jeden Eingang.</p>',22)])])}const g=n(r,[["render",l]]);export{p as __pageData,g as default};
